template.solver:
def solve(r, y, g, t1, t2):
    total = r + y + g
    for k in range(total, -1, -1):
        N = total - k
        good = True
        for a in range(0, r + 1):
            for b in range(0, y + 1):
                c = N - a - b
                if c < 0 or c > g:
                    continue
                cnt = [a, b, c]
                ok = False
                for i in range(3):
                    for j in range(3):
                        if i != j and cnt[i] >= t1 and cnt[j] >= t2:
                            ok = True
                if not ok:
                    good = False
        if good:
            return k
    return -1
